CREATE TABLE IF NOT EXISTS users (id BIGINT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(120) NOT NULL, email VARCHAR(180) UNIQUE NOT NULL, role ENUM('student','admin') NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS items (id BIGINT AUTO_INCREMENT PRIMARY KEY, reporter_id BIGINT NOT NULL, kind ENUM('lost','found') NOT NULL, title VARCHAR(180) NOT NULL, category VARCHAR(80) NOT NULL, description TEXT NOT NULL, location VARCHAR(180) NOT NULL, event_date DATE NOT NULL, image_url TEXT, reward DECIMAL(10,2), contact_phone VARCHAR(30), status ENUM('open','claimed','closed') NOT NULL DEFAULT 'open', created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (reporter_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS matches (id BIGINT AUTO_INCREMENT PRIMARY KEY, lost_item_id BIGINT NOT NULL, found_item_id BIGINT NOT NULL, category_score DECIMAL(5,2) NOT NULL, location_score DECIMAL(5,2) NOT NULL, date_score DECIMAL(5,2) NOT NULL, keyword_score DECIMAL(5,2) NOT NULL, overall_score DECIMAL(5,2) NOT NULL, status ENUM('suggested','claimed','verified','rejected') NOT NULL DEFAULT 'suggested', created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE KEY unique_match_pair (lost_item_id, found_item_id), FOREIGN KEY (lost_item_id) REFERENCES items(id), FOREIGN KEY (found_item_id) REFERENCES items(id));
CREATE TABLE IF NOT EXISTS claims (id BIGINT AUTO_INCREMENT PRIMARY KEY, match_id BIGINT NOT NULL, claimant_id BIGINT NOT NULL, evidence TEXT NOT NULL, status ENUM('pending','approved','rejected') NOT NULL DEFAULT 'pending', reviewed_by BIGINT, reviewed_at TIMESTAMP NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (match_id) REFERENCES matches(id), FOREIGN KEY (claimant_id) REFERENCES users(id), FOREIGN KEY (reviewed_by) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS notifications (id BIGINT AUTO_INCREMENT PRIMARY KEY, user_id BIGINT NOT NULL, type VARCHAR(80) NOT NULL, message TEXT NOT NULL, claim_id BIGINT, read_at TIMESTAMP NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (user_id) REFERENCES users(id), FOREIGN KEY (claim_id) REFERENCES claims(id));
CREATE TABLE IF NOT EXISTS traffic_events (id BIGINT AUTO_INCREMENT PRIMARY KEY, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX items_match_filter ON items(kind, category, status, event_date);
CREATE FULLTEXT INDEX items_search ON items(title, description);
CREATE INDEX claims_review_queue ON claims(status, created_at);
